package com.optarena.app

import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.status

@SpringBootTest
@AutoConfigureMockMvc
class ShippingHiddenTest {

    @Autowired
    lateinit var mvc: MockMvc

    private fun quote(body: String, expectedCost: Int) {
        mvc.perform(post("/shipping/quote").contentType("application/json").content(body))
            .andExpect(status().isOk)
            .andExpect(jsonPath("\$.cost").value(expectedCost))
    }

    @Test
    fun weightBands() {
        quote("""{"weightKg": 0.5, "express": false}""", 5)
        quote("""{"weightKg": 1.0, "express": false}""", 5)
        quote("""{"weightKg": 1.1, "express": false}""", 9)
        quote("""{"weightKg": 10.0, "express": false}""", 9)
        quote("""{"weightKg": 10.5, "express": false}""", 20)
    }

    @Test
    fun expressDoubles() {
        quote("""{"weightKg": 0.5, "express": true}""", 10)
        quote("""{"weightKg": 5.0, "express": true}""", 18)
        quote("""{"weightKg": 25.0, "express": true}""", 40)
    }
}

