package com.optarena.app

import org.springframework.stereotype.Service

@Service
class ShippingService {

    fun cost(weightKg: Double, express: Boolean): Int {
        val base = when {
            weightKg <= 1.0 -> 5
            weightKg <= 10.0 -> 9
            else -> 20
        }
        return if (express) base * 2 else base
    }
}

package com.optarena.app

import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RestController

data class QuoteRequest(val weightKg: Double, val express: Boolean)

@RestController
class ShippingController(private val shippingService: ShippingService) {

    @PostMapping("/shipping/quote")
    fun quote(@RequestBody request: QuoteRequest): Map<String, Int> =
        mapOf("cost" to shippingService.cost(request.weightKg, request.express))
}

